<?php
namespace Tests\Feature;
use App\Models\QueueTicket;
use App\Models\ServiceCategory;
use App\Models\ServiceLocation;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class QueueTest extends TestCase { use RefreshDatabase;
 private function seeded(): array { $this->seed();$location=ServiceLocation::firstOrFail();$category=$location->categories()->firstOrFail();$counter=$location->counters()->firstOrFail();return [$location,$category,$counter]; }
 private function ticket(ServiceLocation $location,ServiceCategory $category,string $name='Test'): QueueTicket { $this->post(route('queue.register',$location),['service_category_id'=>$category->id,'customer_name'=>$name])->assertSessionHasNoErrors();return QueueTicket::latest('id')->firstOrFail(); }
 public function test_public_registration_generates_unique_numbers_and_daily_reset(): void { [$location,$category]=$this->seeded();$a=$this->ticket($location,$category,'Alice');$b=$this->ticket($location,$category,'Bob');$this->assertSame('G-001',$a->display_number);$this->assertSame('G-002',$b->display_number);$this->travelTo(now()->addDay());$c=$this->ticket($location,$category);$this->assertSame('G-001',$c->display_number);$this->assertNotSame($a->lookup_token,$b->lookup_token); }
 public function test_staff_controls_are_protected_and_transitions_are_enforced(): void { [$location,$category,$counter]=$this->seeded();$ticket=$this->ticket($location,$category);$this->patch(route('queue.transition',$ticket),['action'=>'complete'])->assertRedirect('/login');$staff=User::factory()->create();$staff->forceFill(['role'=>'staff'])->save();$this->actingAs($staff)->get('/dashboard')->assertOk();$this->actingAs($staff)->post(route('queue.next',$location),['counter_id'=>$counter->id])->assertSessionHasNoErrors();$ticket->refresh();$this->assertSame('called',$ticket->status);$this->actingAs($staff)->patch(route('queue.transition',$ticket),['action'=>'serve'])->assertSessionHasNoErrors();$ticket->refresh();$this->assertSame('serving',$ticket->status);$this->actingAs($staff)->patch(route('queue.transition',$ticket),['action'=>'complete'])->assertSessionHasNoErrors();$ticket->refresh();$this->assertSame('completed',$ticket->status);$this->assertDatabaseHas('queue_audits',['queue_ticket_id'=>$ticket->id,'action'=>'complete']);$this->actingAs($staff)->patch(route('queue.transition',$ticket),['action'=>'serve'])->assertSessionHasErrors('action'); }
 public function test_public_views_do_not_expose_customer_identity_and_lookup_token_is_required(): void { [$location,$category]=$this->seeded();$ticket=$this->ticket($location,$category,'Private Name');$this->get(route('queue.display',$location))->assertOk()->assertDontSee('Private Name');$this->get(route('queue.ticket',$ticket->lookup_token))->assertOk()->assertSee($ticket->display_number)->assertDontSee('Private Name');$this->get('/my-queue/1')->assertNotFound(); }
 public function test_calls_do_not_cross_locations_and_inactive_category_is_rejected(): void { [$location,$category,$counter]=$this->seeded();$ticket=$this->ticket($location,$category);$other=ServiceLocation::create(['name'=>'Other','slug'=>'other','active'=>true]);$counter2=$other->counters()->create(['name'=>'Other counter','code'=>'X1','active'=>true]);$staff=User::factory()->create();$staff->forceFill(['role'=>'staff'])->save();$this->actingAs($staff)->post(route('queue.next',$other),['counter_id'=>$counter2->id])->assertSessionHas('status','No waiting queue.');$this->assertSame('waiting',$ticket->fresh()->status);$category->update(['active'=>false]);$this->post(route('queue.register',$location),['service_category_id'=>$category->id])->assertSessionHasErrors('category'); }
 public function test_customer_dashboard_redirects_and_report_date_is_validated(): void { $customer=User::factory()->create();$this->actingAs($customer)->get('/dashboard')->assertRedirect(route('queue.home'));$staff=User::factory()->create();$staff->forceFill(['role'=>'staff'])->save();$this->actingAs($staff)->get('/reports?date=not-a-date')->assertSessionHasErrors('date'); }
}
